Hier ist eine C++-Funktion, die auf einen std::string mit Markdown-formatiertem Text verweist und einen std::string mit HTML-formatiertem Text zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <regex>

// Konvertierung von Markdown nach HTML
std::string markdown_to_html(const std::string& markdown) {
    // HTML-Tag für Überschriften
    std::string header_tag(const std::string& level) {
        return "<h" + level + ">";
    }

    // HTML-Tag für Unterstreichung
    std::string underline_tag(const std::string& text) {
        return "<u>" + text + "</u>";
    }

    // HTML-Tag für Hervorhebung
    std::string strong_tag(const std::string& text) {
        return "<strong>" + text + "</strong>";
    }

    // HTML-Tag für Links
    std::string link_tag(const std::string& link, const std::string& text) {
        return "<a href=\"" + link + "\">" + text + "</a>";
    }

    // Konvertierung von Markdown nach HTML
    std::string result;

    // Überschriften
    std::regex header_regex("^#{1,6}(.*)$");
    std::smatch header_match;
    if (std::regex_match(markdown, header_match, header_regex)) {
        std::string level = std::to_string(header_match[1].length()) + " ";
        result += header_tag(level) + header_match[1] + "</h" + level + ">\n";
    } else {
        result += markdown + "\n";
    }

    // Unterstreichung
    std::regex underline_regex("_(. *)_");
    std::smatch underline_match;
    while (std::regex_search(markdown, underline_match, underline_regex)) {
        std::string text = underline_match[1];
        result.replace(underline_match.position(), underline_match.length(), underline_tag(text));
        markdown = markdown.substr(underline_match.position() + underline_match.length());
    }

    // Hervorhebung
    std::regex strong_regex("\\*([^*]*)\\*");
    std::smatch strong_match;
    while (std::regex_search(markdown, strong_match, strong_regex)) {
        std::string text = strong_match[1];
        result.replace(strong_match.position(), strong_match.length(), strong_tag(text));
        markdown = markdown.substr(strong_match.position() + strong_match.length());
    }

    // Links
    std::regex link_regex("\\[(.+?)\\]\\((.*?)\\)");
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string text = link_match[1];
        std::string link = link_match[2];
        result.replace(link_match.position(), link_match.length(), link_tag(link, text));
        markdown = markdown.substr(link_match.position() + link_match.length());
    }

    return result;
}

int main() {
    std::string markdown = "## Hallo Welt!\n"
                           "Dies ist ein *Beispiel* für ein **Markdown-Dokument**.\n"
                           "Klicke [hier](https://google.com) um etwas zu sehen.";

    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

